        movement.x -= 100 * delta
    if is_action_pressed("move_right"):
        movement.x += 100 * delta
    if is_action_pressed("move_up"):
        movement.y -= 100 * delta
    if is_action_pressed("move_down"):
        movement.y += 100 * delta

    movement = clamp(movement, -1000, 1000)
    velocity

